head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[textbox > P > displayFormatter]<br/>렌더링 과정에서 내부 텍스트의 포맷을 변환하기 위한 사용자 정의 함수를 설정합니다.",
    "validation" : [             
        "내부 텍스트의 포맷을 변환할 사용자 정의 함수를 설정할 수 있어야 합니다.",
        "localeRef 속성으로 클라이언트 다국어가 적용되면 해당 속성은 무시되어야 합니다.",
        "사용자 정의 함수의 파라미터로 escape 속성에 의해 이스케이프 처리된 내부 텍스트가 전달되어야 합니다.",
        "사용자 정의 함수의 반환값이 새로운 내부 텍스트로 적용되어야 합니다.",
        "displayFormat 또는 displayFormatter 에 내부 텍스트를 전달한 후 반환값을 최종 사용하여야 합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);    
};



// 사용자 정의 함수
scwin.fn_dpformat = function(val) {
    return "Dear " + val;
};



// 사용자 정의 함수
scwin.fn_escape = function(val) {
    const escapeTable = {
        '&': '&amp;',
        '<': '&lt;',
        '>': '&gt;',
        '"': '&quot;',
        "'": '&apos;'
    };

    return val.replace(/[&<>"']/g, function(match) {
        return escapeTable[match];
    }); 
};



scwin.btn_getText_onclick = function (e) {     
    for(var i =1; i < 6; i ++) {
        wf_body_bottom.getObj("scwin").setReturnValue(eval('target'+i+'.render.textContent'));      
    }    
};
